def validate_payload(payload):
    errors = []

    if not isinstance(payload, dict):
        return [{"field": "request", "message": "request must be an object"}]

    city = payload.get("city")
    if not city:
        errors.append({"field": "city", "message": "city required"})
    elif not isinstance(city, str):
        errors.append({"field": "city", "message": "city must be a string"})

    if "days" in payload:
        days = payload["days"]
        if isinstance(days, bool) or not isinstance(days, int):
            errors.append({"field": "days", "message": "days must be an integer"})
        elif not 1 <= days <= 14:
            errors.append({"field": "days", "message": "days out of range"})

    if "units" in payload:
        units = payload["units"]
        if not isinstance(units, str) or units not in ("metric", "imperial"):
            errors.append({"field": "units", "message": "units must be metric or imperial"})

    return errors

